param([ValidateSet('names','loot')][string]$Kind='names',[string]$SqlDirectory='', [switch]$VerifyLiveData)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..");if(!$SqlDirectory){$SqlDirectory="$repo/sql/updates/world"};$out="$repo/build-extractors/runtime-test/layered-$Kind-data/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";$python='C:/Users/Admin/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe'
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 & $python -X utf8 "$PSScriptRoot/prepare_layered_tests.py" prepare --kind $Kind --output $out --sql-directory $SqlDirectory;if($LASTEXITCODE){throw 'Open data generation failed'};$cases=[IO.File]::ReadAllText("$out/cases.json")|ConvertFrom-Json;if($VerifyLiveData){$cases+=@([pscustomobject]@{label='live';refusal=$false})};$db=(Get-Content "$repo/build-extractors/bin/Release/worldserver.conf"|Where-Object {$_ -match '^WorldDatabaseInfo\s*='}).Split('"')[1].Split(';')
 foreach($case in $cases){$stem="$out/$($case.label)";$prior=$env:MYSQL_PWD;try{$env:MYSQL_PWD=$db[3];$arguments=@("--host=$($db[0])","--port=$($db[1])","--user=$($db[2])","--database=$($db[4])",'--batch','--raw','--skip-column-names');if($case.refusal){$arguments+='--force'};$code=& "$PSScriptRoot/Invoke-NativeSqlFiles.ps1" -Executable C:/wamp64/bin/mariadb/mariadb11.4.9/bin/mysql.exe -Arguments $arguments -InputFile "$stem.sql" -OutputFile "$stem.tsv" -ErrorFile "$stem.stderr"}finally{$env:MYSQL_PWD=$prior};@{exit=$code;expected_refusal=[bool]$case.refusal}|ConvertTo-Json|Set-Content "$stem-status.json";$errors=[IO.File]::ReadAllText("$stem.stderr");if($case.refusal){if($code -or $errors -notmatch '\A--------------\r?\nEXECUTE layered_guard\r?\n--------------\r?\n\r?\nERROR 1644 \(45000\) at line \d+: Layered repair row/source differs; review before updating\r?\n?\z'){throw 'Open exact refusal differs'}}elseif($code -or $errors.Length){throw 'Open SQL failed'}}
 $arguments=@('-X','utf8',"$PSScriptRoot/prepare_layered_tests.py",'verify','--kind',$Kind,'--output',$out,'--sql-directory',$SqlDirectory);if($VerifyLiveData){$arguments+='--live'};& $python @arguments;if($LASTEXITCODE){throw 'Open data assertions failed'}
}
